INSERT INTO "TeamMember" ("id", "name", "role", "photo", "photoAlt", "bio", "group", "shown", "sortOrder", "updatedAt") VALUES ('tm_team_01', 'Md. Rahman', 'Founder & CEO', '/images/team/member-1.svg', 'Md. Rahman, Founder & CEO at GlobalEd', '12+ years in international education consultancy.', 'TEAM', true, 0, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "TeamMember" ("id", "name", "role", "photo", "photoAlt", "bio", "group", "shown", "sortOrder", "updatedAt") VALUES ('tm_team_02', 'Sarah Ahmed', 'Head of Counselling', '/images/team/member-2.svg', 'Sarah Ahmed, Head of Counselling at GlobalEd', 'Certified counsellor for UK, Canada, and Australia admissions.', 'TEAM', true, 1, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "TeamMember" ("id", "name", "role", "photo", "photoAlt", "bio", "group", "shown", "sortOrder", "updatedAt") VALUES ('tm_team_03', 'Tanvir Hasan', 'IELTS Chief Instructor', '/images/team/member-3.svg', 'Tanvir Hasan, IELTS Chief Instructor at GlobalEd', 'Band 8.5 mentor with 10 years of IELTS teaching experience.', 'TEAM', true, 2, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "TeamMember" ("id", "name", "role", "photo", "photoAlt", "bio", "group", "shown", "sortOrder", "updatedAt") VALUES ('tm_team_04', 'Nusrat Jahan', 'Visa Documentation Lead', '/images/team/member-4.svg', 'Nusrat Jahan, Visa Documentation Lead at GlobalEd', 'Specialist in visa file preparation and compliance checks.', 'TEAM', true, 3, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "TeamMember" ("id", "name", "role", "photo", "photoAlt", "bio", "group", "shown", "sortOrder", "updatedAt") VALUES ('tm_team_05', 'Arif Chowdhury', 'Senior Education Counsellor', '/images/team/member-5.svg', 'Arif Chowdhury, Senior Education Counsellor at GlobalEd', 'Europe destinations expert — Sweden, Finland, Denmark, and Malta.', 'TEAM', true, 4, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "TeamMember" ("id", "name", "role", "photo", "photoAlt", "bio", "group", "shown", "sortOrder", "updatedAt") VALUES ('tm_team_06', 'Priya Das', 'Student Support Manager', '/images/team/member-6.svg', 'Priya Das, Student Support Manager at GlobalEd', 'Leads pre-departure briefings and post-arrival student care.', 'TEAM', true, 5, CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
